import"./modulepreload-polyfill-B5Qt9EMX.js";/* empty css              */import{t as e}from"./toast-Cexsccug.js";const n=document.getElementById("login-form");n.addEventListener("submit",async o=>{o.preventDefault();const r=document.getElementById("email").value.trim(),a=document.getElementById("password").value.trim();try{const t=await(await fetch("http://localhost:3000/api/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:r,password:a})})).json();if(!t.success){e.error(t.error);return}localStorage.setItem("token",t.data.token),localStorage.setItem("user",JSON.stringify(t.data.user)),e.success(t.message),setTimeout(()=>{t.data.user.role==="admin"?window.location.href="admin.html":window.location.href="index.html"},1e3)}catch{e.error("Unable to connect to the server")}});
